// Generates src/generated from the Degroshi public API spec. Never edit src/generated by hand: run `bun run generate`
// and commit the result. DEGROSHI_OPENAPI_SPEC points at another copy of the spec (a path or a URL).
import { defineConfig } from "@hey-api/openapi-ts"

export default defineConfig({
  input: process.env.DEGROSHI_OPENAPI_SPEC ?? "https://docs.degroshi.com/public-openapi.json",
  // Node ESM needs the extension in every relative import.
  output: { path: "src/generated", importFileExtension: ".js" },
  plugins: ["@hey-api/client-fetch", "@hey-api/typescript", "@hey-api/sdk"],
})
